-- 2차 묶음 6 되돌리기: 백업 테이블의 원문으로 117개 행을 복원한다. DO 블록 하나라 실패하면 전부 취소된다.
DO $rollback_v2_6$
DECLARE
  v_payload jsonb := $payload$[{"id": 627, "word": "파레토최적", "beforeLength": 330, "after": "누군가에게 손해를 주지 않고서는 다른 사람을 더 낫게 만들 수 없는 자원 배분 상태예요. 한 사람의 만족을 높이려면 반드시 다른 사람의 만족이 줄어드는 상황이라 더 이상 개선할 여지가 없어요. 다만 효율만 따질 뿐 소득이 공평하게 나뉘었는지는 말해 주지 못해요."}, {"id": 628, "word": "파생금융상품", "beforeLength": 730, "after": "통화·채권·주식 같은 기초자산의 가격 움직임에 따라 가치가 정해지는 금융상품이에요. 미래에 정한 값으로 사고팔기로 약속하는 선물, 사고팔 권리를 거래하는 옵션, 현금흐름을 맞바꾸는 스왑 등이 있어요. 위험을 줄이는 데 쓰이지만 적은 돈으로 큰 거래를 할 수 있어 손실도 커질 수 있어요."}, {"id": 629, "word": "페더럴펀드", "beforeLength": 1005, "after": "미국 은행들이 지급준비금이 모자라거나 남을 때 담보 없이 서로 빌리고 빌려주는 초단기 자금이에요. 대부분 하루짜리로 거래되고, 여기에 붙는 금리가 미국의 대표적인 단기금리예요. 미국 중앙은행인 연준이 이 금리의 목표 범위를 정책금리로 삼기 때문에 세계 금융시장이 주목해요."}, {"id": 630, "word": "평잔", "beforeLength": 550, "after": "일정 기간 동안 매일의 잔액을 모두 더한 뒤 날짜 수로 나눈 평균 잔액이에요. 예를 들어 한 달 평균이라면 그달 하루하루 잔액을 합쳐 30이나 31로 나눠요. 마지막 날에만 잔액이 잠깐 줄거나 느는 왜곡을 피할 수 있어 이자 계산이나 수익 평가에 많이 써요."}, {"id": 631, "word": "표면금리", "beforeLength": 376, "after": "채권에 적혀 있는 이자율로, 액면가를 기준으로 1년에 얼마의 이자를 줄지 약속한 비율이에요. 액면가 1만 원짜리 채권의 이 비율이 3%라면 해마다 300원의 이자를 받아요. 시장금리가 이보다 낮아지면 채권값은 액면가보다 비싸지고, 높아지면 싸져요."}, {"id": 632, "word": "풋옵션", "beforeLength": 611, "after": "정해진 기간 안에 미리 약속한 가격으로 어떤 자산을 팔 수 있는 권리예요. 산 사람은 판 사람에게 프리미엄이라는 대가를 내고, 자산값이 약속 가격보다 떨어지면 권리를 써서 차익을 얻어요. 값이 오르면 권리를 포기하면 되므로 손실은 낸 프리미엄으로 한정돼요."}, {"id": 633, "word": "프로그램매매", "beforeLength": 557, "after": "컴퓨터 프로그램이 미리 정한 조건에 따라 여러 종목의 주식을 한꺼번에 사고파는 매매 방식이에요. 현물과 선물의 가격 차이를 노리는 차익거래와, 선물과 상관없이 종목 묶음을 일괄 매매하는 비차익거래로 나뉘어요. 주로 기관과 외국인이 쓰며 규모가 커서 지수 흐름에 큰 영향을 줄 수 있어요."}, {"id": 634, "word": "프로젝트 파이낸싱", "beforeLength": 759, "after": "발전소·도로·부동산 개발 같은 큰 사업에 필요한 돈을 사업 자체의 미래 수익을 믿고 빌려주는 금융이에요. 보통 사업만 따로 맡는 특수목적회사를 세우고, 여러 금융기관이 함께 돈을 대며 위험을 나눠요. 회사의 신용이나 담보보다 사업성이 핵심이라 사업이 잘못되면 돈을 돌려받기 어려워져요."}, {"id": 635, "word": "프로젝트 한강", "beforeLength": 920, "after": "한국은행이 중앙은행 디지털화폐와 예금토큰을 실제 생활에서 쓸 수 있는지 시험하는 사업이에요. 은행 예금을 디지털 토큰으로 바꿔 물건값을 내고, 은행끼리는 디지털화폐로 바로 정산하는 구조를 점검해요. 용도와 기간을 정해 둔 디지털 바우처처럼 정책자금을 투명하게 쓰는 방법도 함께 실험해요."}, {"id": 636, "word": "플라자 합의", "beforeLength": 560, "after": "1985년 미국·일본·서독·프랑스·영국 다섯 나라가 뉴욕의 한 호텔에 모여 달러 가치를 낮추기로 한 합의예요. 지나친 달러 강세로 미국 무역적자가 커지자 엔화와 마르크화 가치를 함께 끌어올렸어요. 이후 엔화가 크게 오르면서 일본에 거품과 장기 불황이 이어진 계기로 자주 언급돼요."}, {"id": 637, "word": "플랫폼 노동자", "beforeLength": 143, "after": "배달앱처럼 온라인 플랫폼을 통해 일감을 받고 그 대가를 받는 사람이에요. 스마트폰 앱으로 원하는 시간에 일을 골라 할 수 있어 빠르게 늘어나고 있어요. 일하는 방식은 자유롭지만 사회보험이나 안전 보호가 부족해 제도 보완이 필요하다는 지적이 많아요."}, {"id": 638, "word": "피셔효과", "beforeLength": 901, "after": "명목금리는 실질금리에 앞으로 예상되는 물가상승률을 더한 값이라는 생각에서 나온 이론이에요. 실질금리가 그대로라면 사람들이 물가가 2%p 더 오를 거라 예상할 때 명목금리도 그만큼 올라요. 그래서 금리가 올랐을 때 실질금리 때문인지 물가 기대 때문인지 나눠 보는 데 쓰여요."}, {"id": 639, "word": "피용자보수", "beforeLength": 145, "after": "회사 등에 고용된 사람이 일한 대가로 받는 임금·급여 같은 소득을 모두 합친 거예요. 생산으로 생긴 소득은 노동·자본 등을 제공한 사람에게 나뉘는데, 그중 노동자의 몫이 여기에 해당해요. 국민소득이 근로자와 기업에 어떻게 나뉘는지 볼 때 기본이 되는 통계예요."}, {"id": 640, "word": "피용자보수비율", "beforeLength": 509, "after": "나라 전체 국민소득 가운데 근로자가 임금으로 받아 간 몫이 얼마인지를 나타낸 비율이에요. 한국은행은 근로자 몫과 기업 쪽 몫인 영업잉여를 합친 소득에서 근로자 몫이 차지하는 비중으로 계산해요. 노동소득분배율의 하나로, 소득이 노동과 자본 사이에 어떻게 나뉘는지 분석할 때 써요."}, {"id": 641, "word": "핀테크", "beforeLength": 665, "after": "금융과 기술을 합친 말로, 디지털 기술로 금융 서비스를 더 편리하게 바꾸거나 새로 만드는 것이에요. 모바일 간편송금, 인터넷전문은행, 로보어드바이저, P2P대출 등이 대표적인 사례예요. 기존 금융회사의 효율을 높이기도 하고, IT기업이 낮은 수수료로 은행과 경쟁하기도 해요."}, {"id": 642, "word": "필립스곡선", "beforeLength": 493, "after": "단기적으로 실업률과 물가상승률이 서로 반대로 움직이는 관계를 나타낸 곡선이에요. 1958년 실업률이 낮은 해엔 임금이 많이 오르고 높은 해엔 적게 오른다는 관찰에서 나왔어요. 실업을 줄이면 물가가 오르기 쉽다는 맞교환 관계를 보여 줘 경제정책 논의에 자주 쓰여요."}, {"id": 643, "word": "한계비용", "beforeLength": 604, "after": "물건을 한 개 더 만들 때 추가로 늘어나는 비용이에요. 빵 50개를 만드는 데 10만 원, 51개에 10만 1,500원이 든다면 51번째 빵의 추가 비용은 1,500원이에요. 기업은 한 개 더 팔아 얻는 수입과 이 비용을 비교해 생산량을 정하기 때문에 이윤 계산에 꼭 필요해요."}, {"id": 644, "word": "한계소비성향", "beforeLength": 221, "after": "소득이 새로 늘어났을 때 그 늘어난 몫 중 소비에 쓰는 비율이에요. 월급이 10만 원 올라 그중 7만 원을 더 쓴다면 이 비율은 0.7이에요. 보통 저소득층일수록 높게 나타나서 소득 지원이 소비를 얼마나 늘릴지 가늠할 때 쓰여요."}, {"id": 645, "word": "한계효용", "beforeLength": 158, "after": "어떤 것을 한 단위 더 소비할 때 추가로 얻는 만족이에요. 배고플 때 먹는 첫 번째 빵은 아주 맛있지만 두세 번째로 갈수록 더해지는 만족은 줄어들어요. 이렇게 소비량이 늘수록 추가 만족이 작아지는 것을 체감의 법칙이라고 불러요."}, {"id": 646, "word": "한국은행", "beforeLength": 444, "after": "1950년에 설립된 우리나라의 중앙은행이에요. 기준금리를 정하는 등 통화신용정책을 펴고, 지폐와 동전을 발행할 수 있는 유일한 기관이에요. 법에 정해진 가장 중요한 목표는 물가안정이고, 2011년부터는 금융안정에도 유의하도록 명시됐어요."}, {"id": 647, "word": "한시적 근로자", "beforeLength": 638, "after": "근로계약 기간이 정해져 있거나, 기간 없이 계약을 반복 갱신하며 일하거나, 원치 않는 사유로 계속 일하기 어려운 사람을 말해요. 계약직·촉탁직 같은 이름과 상관없이 고용이 얼마나 이어질 수 있는지를 기준으로 나눠요. 시간제·비전형 근로자와 함께 비정규직을 이루는 한 갈래예요."}, {"id": 648, "word": "한은금융망(BOK-Wire+)", "beforeLength": 527, "after": "한국은행이 운영하는, 금융기관끼리 큰 금액의 원화를 주고받는 거액결제시스템이에요. 은행들이 한국은행에 둔 당좌예금 계좌 사이에서 돈을 옮기는 방식으로 콜거래나 증권·외환 매매 대금을 처리해요. 실시간 결제와 차액 결제를 섞은 방식이라 결제 위험을 줄이면서 필요한 자금도 아낄 수 있어요."}, {"id": 649, "word": "할당관세제도", "beforeLength": 326, "after": "정부가 정한 수입 수량까지는 낮은 관세를, 그 양을 넘으면 높은 관세를 매기는 제도예요. 국내 생산만으로 수요를 다 채우지 못하는 물건을 값싸게 들여오면서도 지나친 수입은 막으려는 목적이에요. 소비자와 국내 생산자의 요구를 함께 맞추는 장치로, 국제적으로도 허용돼요."}, {"id": 650, "word": "합계출산율", "beforeLength": 593, "after": "지금의 연령별 출산율이 이어진다고 가정할 때 여성 한 명이 15~49세에 낳을 것으로 예상되는 평균 자녀 수예요. 나이별 출산율을 여성 1명 기준으로 바꿔 모두 더해서 구해요. 인구를 현재 수준으로 유지하려면 대략 2.1명이 필요하다고 보는데, 우리나라는 이보다 훨씬 낮아요."}, {"id": 652, "word": "헤지펀드", "beforeLength": 630, "after": "소수의 큰손 투자자에게서 돈을 모아 높은 수익을 노리고 공격적으로 굴리는 사모펀드예요. 주식·채권뿐 아니라 파생상품에도 투자하고, 빌린 돈까지 더해 투자 규모를 크게 키우는 경우가 많아요. 일반인에게 공개 모집하는 뮤추얼펀드와 달리 규제를 덜 받는 편이라 위험도 그만큼 커요."}, {"id": 653, "word": "현금자동인출기(CD)공동망", "beforeLength": 414, "after": "어느 은행 고객이든 다른 은행의 현금인출기에서 돈을 찾거나 이체할 수 있도록 은행 전산을 서로 이어 놓은 망이에요. 금융결제원이 가운데서 각 은행 시스템을 연결해 거래 정보를 중계해요. 덕분에 내 은행 지점을 찾지 않아도 되고, 무인점포가 빨리 퍼지는 계기가 됐어요."}, {"id": 654, "word": "현시비교우위지수(RCA)", "beforeLength": 730, "after": "한 나라가 어떤 품목 수출에서 세계 평균에 비해 얼마나 경쟁력이 있는지 보여 주는 지수예요. 그 나라 전체 수출 중 해당 품목 비중을, 세계 전체 수출 중 같은 품목 비중으로 나눠 구해요. 값이 1보다 크면 그 품목에 비교우위가 있다고 보고, 클수록 강점이 크다고 해석해요."}, {"id": 655, "word": "현용화폐", "beforeLength": 742, "after": "지금 우리나라에서 법적으로 쓸 수 있는 한국은행 발행 지폐와 동전이에요. 금액 제한 없이 모든 거래에서 지급수단으로 인정되고, 이것으로 값을 치르면 빚이 갚아진 것으로 봐요. 지폐는 오만원권·만원권·오천원권·천원권, 동전은 오백원부터 일원까지 여섯 종류가 있어요."}, {"id": 656, "word": "현지금융", "beforeLength": 615, "after": "국내 기업이나 그 해외 지점·현지법인이 외국에서 쓰려고 외국에서 외화를 빌리거나 지급보증을 받는 것이에요. 해외에 투자한 기업이나 해외건설업체가 현지 금융기관에서 자금을 조달할 때 주로 이용해요. 이렇게 빌린 돈이 국내로 들어오면 금융시장을 흔들 수 있어 국내 유입은 제한돼 왔어요."}, {"id": 657, "word": "현지법인", "beforeLength": 455, "after": "국내 기업이 외국에 진출하면서 그 나라 법에 따라 세운 별도의 회사예요. 해외시장을 넓히거나 싼 인건비로 생산하거나 현지 기술·정보를 얻으려고 주로 세워요. 사무소나 지점보다 할 수 있는 영업 범위가 넓은 대신 자금이 더 많이 들고 관리도 더 엄격해요."}, {"id": 658, "word": "협의통화(M1)", "beforeLength": 379, "after": "현금과 언제든 바로 꺼내 쓸 수 있는 예금만 합친 가장 좁은 범위의 통화량이에요. 지폐·동전에 보통예금·당좌예금 같은 요구불예금과 수시입출식 저축성예금이 들어가요. 곧바로 쓸 수 있는 돈의 양이라 단기 경기 흐름을 볼 때 쓰이고, 범위를 넓히면 광의통화(M2)가 돼요."}, {"id": 659, "word": "혼합형결제시스템", "beforeLength": 600, "after": "거래마다 바로 결제하는 방식의 안전함과, 서로 상계해 차액만 결제하는 방식의 자금 절약을 합친 거액결제시스템이에요. 차액 정산을 하루 끝으로 미루지 않고 영업시간 중에 수시로 처리해 결제가 빨리 끝나요. 우리나라는 2009년 한은금융망에 이 방식을 도입했어요."}, {"id": 660, "word": "홀로그램", "beforeLength": 584, "after": "지폐를 기울이면 보는 각도에 따라 그림이 바뀌어 보이는 위조방지 장치예요. 레이저 빛의 간섭을 이용해 입체 이미지를 기록하기 때문에 복사하면 이 효과가 나타나지 않아요. 오만원권에는 띠 모양으로, 만원권과 오천원권에는 작은 조각 모양으로 붙어 있어요."}, {"id": 661, "word": "화폐교환", "beforeLength": 430, "after": "찢어지거나 불에 타는 등 손상된 돈을 쓸 수 있는 돈으로 바꿔 주는 것이에요. 손상된 지폐는 남은 면적이 4분의 3 이상이면 전액, 5분의 2 이상이면 반액을 받고 그보다 적으면 바꿀 수 없어요. 동전은 모양을 알아볼 수 있고 진짜인지 확인되면 액면 그대로 바꿔 줘요."}, {"id": 662, "word": "화폐발행액", "beforeLength": 263, "after": "한국은행이 발행해 한국은행 밖에 나가 있는 지폐와 동전의 총액이에요. 한국은행이 국공채나 외환을 사들이거나 은행에 대출해 줄 때 돈이 시중으로 풀려요. 사람들이 가진 현금과 금융기관 금고의 현금을 합친 값이라, 돈이 다시 한국은행으로 돌아오면 줄어들어요."}, {"id": 663, "word": "화폐의 액면체계", "beforeLength": 602, "after": "천원·오천원·만원처럼 한 나라 화폐가 어떤 액면 금액들로 구성되는지를 나타낸 틀이에요. 1·5 단위로 늘리는 방식과 1·2·5 단위로 늘리는 방식이 대표적인데, 우리나라는 1·5 방식을 써요. 액면 종류가 적으면 구분하기 쉽지만 거래에 필요한 지폐 장수가 많아지는 단점이 있어요."}, {"id": 664, "word": "환경계정", "beforeLength": 697, "after": "경제활동과 환경의 관계를 기록하려고 국민계정에 덧붙여 만든 환경경제통합계정이에요. 숲·광물·물 같은 자연도 생산에 쓰이는 자산으로 보고, 자원이 줄거나 오염된 만큼을 돈으로 따져 기록해요. 이 손실을 국내순생산에서 빼면 흔히 녹색GDP라 부르는 환경 조정 지표를 얻을 수 있어요."}, {"id": 665, "word": "환경권", "beforeLength": 434, "after": "모든 국민이 건강하고 쾌적한 환경에서 살 수 있는 권리예요. 우리 헌법 제35조에 규정돼 있고, 국가와 국민 모두 환경을 지키려고 노력해야 한다고 정하고 있어요. 오염으로 피해를 입지 않을 권리뿐 아니라 국가에 깨끗한 환경을 만들어 달라고 요구할 권리도 포함돼요."}, {"id": 666, "word": "환리스크", "beforeLength": 431, "after": "환율이 예상과 다르게 움직여 외화로 가진 자산이나 갚아야 할 빚의 가치가 달라질 위험이에요. 수출 계약 뒤 대금을 받기 전에 환율이 떨어지면 원화로 받는 돈이 줄어드는 것이 대표적인 경우예요. 거래 시점 차이에서 생기는 거래위험과 장부상 환산 과정에서 생기는 환산위험으로 나뉘어요."}, {"id": 667, "word": "환리스크 헤지", "beforeLength": 255, "after": "환율 변동 때문에 외화 자산·부채나 앞으로 들어올 돈의 가치가 흔들리는 위험을 미리 없애는 것이에요. 선물환으로 미래 환율을 지금 고정하거나 통화옵션·통화스왑, 환변동보험 같은 수단을 써요. 수출입 기업은 이렇게 해서 환율이 크게 움직여도 이익 계획이 흔들리지 않게 해요."}, {"id": 668, "word": "환매조건부매매(RP)", "beforeLength": 342, "after": "나중에 정해진 가격으로 다시 사들이기로 약속하고 채권을 파는 거래예요. 형식은 채권 매매지만, 실제로는 채권을 담보로 맡기고 짧은 기간 돈을 빌리는 것과 같아요. 금융기관과 고객 사이, 금융기관끼리 쓰이고 한국은행이 시중 돈의 양을 조절할 때도 활용해요."}, {"id": 669, "word": "환어음", "beforeLength": 209, "after": "발행한 사람이 직접 돈을 주지 않고, 제3자인 지급인에게 받을 사람에게 돈을 주라고 맡기는 어음이에요. 그래서 발행인 말고 지급인이 따로 있어야 하고, 지급인이 인수해야 지급 의무가 확정돼요. 발행인이 직접 갚겠다고 약속하는 약속어음과 다르고, 무역 대금 결제에 많이 쓰여요."}, {"id": 670, "word": "환율조작국", "beforeLength": 690, "after": "미국이 자국과의 교역에서 큰 흑자를 내면서 환율에 부당하게 개입한다고 판단해 지정하는 나라예요. 미국 재무부는 대미 무역흑자, 경상수지 흑자, 외환시장 개입 규모를 기준으로 주요 교역국을 정기적으로 평가해요. 지정되면 미국의 협의 요구와 통상 압박을 받을 수 있어요."}, {"id": 671, "word": "환전영업자(환전상)", "beforeLength": 501, "after": "외국 돈을 사고팔거나 외국에서 발행한 여행자수표를 사들이는 일을 하는 곳이에요. 외화를 사는 것이 기본 업무이고, 파는 것은 일정 금액 이하로 제한되는 등 규칙이 정해져 있어요. 1999년부터 허가 대신 등록만 하면 영업할 수 있게 돼 공항이나 관광지에서 흔히 볼 수 있어요."}, {"id": 672, "word": "환차손", "beforeLength": 629, "after": "환율이 바뀌면서 외화 자산이나 부채를 원화로 다시 따졌을 때 생기는 손실이에요. 달러 예금을 가지고 있는데 원·달러 환율이 떨어지면 원화로 바꾼 가치가 줄어 손해가 나요. 반대로 달러 빚이 있을 때는 환율이 오르면 갚을 원화가 늘어나 손실이 생겨요."}, {"id": 673, "word": "회사채", "beforeLength": 752, "after": "민간 기업이 설비투자 같은 데 쓸 큰돈을 비교적 오래 빌리려고 발행하는 채권이에요. 기업은 정해진 날에 이자를 주고 만기에 원금을 갚겠다고 약속하며, 증권사 등이 인수해 투자자에게 팔아요. 국채보다 떼일 위험이 커서 같은 만기의 국채보다 금리가 높게 붙어요."}, {"id": 674, "word": "후방연쇄효과", "beforeLength": 404, "after": "어떤 산업이 생산을 늘릴 때 그 산업에 원자재와 부품을 대는 산업의 생산도 함께 늘어나는 효과예요. 자동차 생산이 늘면 철강·유리·전자부품 산업의 주문도 늘어나는 식이에요. 반대로 그 산업의 제품을 사서 쓰는 쪽으로 퍼지는 효과는 전방연쇄효과라고 불러요."}, {"id": 675, "word": "후순위금융채", "beforeLength": 326, "after": "은행이 망했을 때 예금자 같은 다른 채권자에게 다 갚은 뒤에야 돌려받을 수 있는 채권이에요. 갚는 순서가 뒤로 밀리는 대신 금리가 높고, 일정 조건을 갖추면 은행 자본의 일부로 인정돼요. 그래서 은행이 자기자본비율을 높이려고 발행하는 경우가 많아요."}, {"id": 677, "word": "4차 산업혁명", "beforeLength": 767, "after": "인공지능·빅데이터·사물인터넷 같은 새로운 정보통신기술이 산업과 사회 전반을 근본적으로 바꾸는 변화예요. 증기기관, 전기와 대량생산, 컴퓨터와 인터넷에 이은 네 번째 큰 기술 변혁이라는 뜻이에요. 일하는 방식과 기업 경영, 노동시장까지 크게 바꿀 것으로 보여 많은 나라가 대비하고 있어요."}, {"id": 678, "word": "BIS 자기자본비율", "beforeLength": 1199, "after": "은행이 가진 자산의 위험 정도를 반영해 계산한 금액 대비 자기자본이 얼마나 되는지 나타낸 비율이에요. 국제결제은행 산하 바젤위원회가 정한 국제 기준으로, 위험한 자산일수록 더 큰 가중치를 매겨 계산해요. 최소 8% 이상을 유지해야 하고, 높을수록 손실이 나도 버틸 힘이 크다는 뜻이에요."}, {"id": 679, "word": "CAMEL-IR 방식", "beforeLength": 739, "after": "금융감독당국이 은행 본점과 해외 현지법인의 경영 상태를 평가할 때 쓰는 방식이에요. 자본적정성, 자산건전성, 경영관리, 수익성, 유동성, 내부통제, 리스크관리 부문별로 점수를 매겨요. 그 결과로 종합 등급을 정하고, 등급에 따라 감독의 강도를 정하는 데 활용해요."}, {"id": 680, "word": "CDS프리미엄", "beforeLength": 426, "after": "채권을 낸 기업이나 나라가 부도날 때 손실을 보상받는 계약에 내는 보험료 같은 수수료예요. 부도 위험이 크다고 여겨질수록 보상받기 위해 내야 하는 이 수수료가 비싸져요. 그래서 한 나라의 신용 상태를 시장에서 바로 보여 주는 지표로 국제금융시장에서 많이 쓰여요."}, {"id": 681, "word": "CLS은행", "beforeLength": 425, "after": "여러 나라 통화가 오가는 외환거래를 동시에 결제해 주는 국제 외환결제 전문은행이에요. 거래 양쪽 통화를 같은 순간에 주고받게 해, 내 돈만 보내고 상대 돈을 못 받는 위험을 없애요. 1999년 주요 국제은행들이 국제결제은행의 권고에 따라 설립했고, 원화도 결제 대상에 들어 있어요."}, {"id": 682, "word": "CMO", "beforeLength": 816, "after": "주택담보대출에서 나오는 원리금 흐름을 기초로, 만기와 위험이 다른 여러 층으로 나눠 발행하는 미국의 증권이에요. 들어온 돈을 정해진 순서에 따라 앞쪽 층부터 먼저 갚는 식으로 설계해 층마다 성격이 달라져요. 투자자는 원하는 만기와 위험 수준에 맞는 층을 골라 투자할 수 있어요."}, {"id": 683, "word": "EC방식", "beforeLength": 673, "after": "1972년 유럽공동체가 회원국에 권고한, 경제에 알맞은 통화량 규모를 계산하는 방식이에요. 경제성장률과 물가상승률 목표 등을 고려해 통화량이 얼마나 늘어야 적정한지 정하고 그 목표에 맞춰 관리해요. 1970년대 높은 인플레이션 속에서 금리보다 통화량 관리를 중시하던 흐름을 보여 줘요."}, {"id": 684, "word": "ESG경영", "beforeLength": 651, "after": "환경·사회·지배구조 세 가지를 중시하며 기업을 운영하는 방식이에요. 탄소 배출을 줄이고, 노동자와 지역사회를 배려하며, 투명하고 공정한 의사결정 구조를 갖추는 것이 대표적인 실천이에요. 이윤만이 아니라 장기적인 기업가치와 지속가능성을 평가하는 기준으로 투자자들도 주목해요."}, {"id": 685, "word": "ESTR", "beforeLength": 357, "after": "유럽중앙은행이 매일 발표하는 유로지역의 하루짜리 무담보 단기 기준금리예요. 주요 은행들의 하루짜리 무담보 차입 거래에서 금리 양 끝 25%씩을 빼고 나머지를 거래액으로 가중평균해 구해요. 조작 논란이 있던 기존 금리를 대신해 2019년부터 쓰이고, 유로화 금리 상품의 기준이 돼요."}, {"id": 686, "word": "FIMA Repo Facility", "beforeLength": 362, "after": "외국 중앙은행이 가진 미국 국채를 담보로 미국 연준이 달러를 빌려주는 제도예요. 국채를 시장에 내다 팔지 않고도 필요할 때 곧바로 달러를 구할 수 있게 해 줘요. 코로나19 때 임시로 도입됐다가 상설 제도가 됐고, 달러가 부족해질 때 대비책으로 쓰여요."}, {"id": 687, "word": "FOMO현상", "beforeLength": 404, "after": "남들은 좋은 기회를 잡는데 나만 놓칠까 봐 불안해하는 심리예요. 주변 사람이 큰돈을 벌었다는 소식에 충분히 따져 보지 않고 서둘러 투자하는 행동으로 이어지기 쉬워요. 변동성이 큰 시장에서 자주 나타나며 자산 가격의 거품을 키우는 원인으로 꼽혀요."}, {"id": 688, "word": "FTSE 지수", "beforeLength": 522, "after": "영국의 지수 회사인 FTSE 러셀이 만들어 발표하는 세계 주가지수예요. 전 세계에 투자하는 대형 펀드, 특히 유럽계 펀드가 나라별로 얼마나 투자할지 정할 때 기준으로 삼아요. 미국의 MSCI 지수와 함께 세계 양대 투자지표로 꼽혀서 편입 여부가 외국인 자금 흐름에 영향을 줘요."}, {"id": 689, "word": "FedWatch", "beforeLength": 352, "after": "금리선물 가격을 바탕으로 미국 연준이 다음 회의에서 금리를 올릴지, 동결할지, 내릴지에 대한 시장의 예상 확률을 보여 주는 지표예요. 시카고상업거래소가 제공하며 동결 확률 70% 같은 식으로 숫자로 나타나요. 연준 위원들의 금리 전망과 비교하면 시장 기대가 얼마나 다른지 알 수 있어요."}, {"id": 690, "word": "G2(Group of Two)", "beforeLength": 448, "after": "세계 경제에서 영향력이 가장 큰 두 나라인 미국과 중국을 함께 부르는 비공식 용어예요. 2000년대 들어 중국이 빠르게 성장해 미국에 버금가는 경제대국이 되면서 쓰이기 시작했어요. 두 나라의 관계와 무역 갈등이 세계 경기와 금융시장에 큰 영향을 줘서 자주 언급돼요."}, {"id": 691, "word": "G20(Group of 20)", "beforeLength": 860, "after": "주요 19개국과 유럽연합, 아프리카연합이 모여 세계 경제 현안을 논의하는 국제회의체예요. 선진 7개국에 한국·중국·인도 같은 신흥국이 더해졌고, 재무장관 회의로 출발했어요. 2008년 글로벌 금융위기 때 정상회의가 열린 뒤 세계 경제 협력을 위한 최상위 협의체가 됐어요."}, {"id": 692, "word": "G7(Group of Seven)", "beforeLength": 813, "after": "미국·일본·영국·프랑스·독일·이탈리아·캐나다 일곱 선진국의 모임이에요. 1970년대 오일쇼크 대응을 위해 다섯 나라 재무장관이 모인 데서 시작해 이탈리아와 캐나다가 합류했어요. 한때 러시아가 참여해 G8이 됐지만 크림반도 사태 이후 다시 일곱 나라 체제로 돌아왔어요."}, {"id": 693, "word": "GDP갭", "beforeLength": 322, "after": "실제 국내총생산에서, 물가를 자극하지 않고 낼 수 있는 최대 생산 수준인 잠재 국내총생산을 뺀 값이에요. 이 값이 플러스면 경제가 능력보다 과열돼 물가가 오르기 쉽고, 마이너스면 수요가 부족해 경기가 처져 있다는 뜻이에요. 그래서 중앙은행이 금리 방향을 정할 때 참고해요."}, {"id": 694, "word": "GDP디플레이터", "beforeLength": 297, "after": "명목 국내총생산을 실질 국내총생산으로 나누고 100을 곱해 구하는 물가지수예요. 소비자물가뿐 아니라 생산자·수출입 가격, 임금 등 경제 안의 여러 가격 변화가 함께 반영돼요. 그래서 나라 경제 전체의 물가 수준을 보여 주는 가장 종합적인 물가지표로 쓰여요."}, {"id": 695, "word": "Herstatt 리스크", "beforeLength": 465, "after": "외환거래에서 내가 팔기로 한 통화는 이미 보냈는데 상대방이 망해 받기로 한 통화를 못 받는 위험이에요. 나라마다 결제 시간이 달라 한쪽 통화만 먼저 지급되는 시차 동안 생겨요. 1974년 독일의 한 은행이 파산하며 실제로 벌어져 그 은행 이름이 붙었어요."}, {"id": 696, "word": "IC카드", "beforeLength": 508, "after": "계산과 암호화를 할 수 있는 반도체 칩을 넣어 만든 카드예요. 예전 자기띠 카드보다 저장할 수 있는 정보가 많고 칩 안에서 정보를 암호화해 복제가 어려워요. 신용·체크·교통카드는 물론 신분증 용도로도 쓰이고, 단말기에 꽂는 접촉식과 대기만 하면 되는 비접촉식이 있어요."}, {"id": 697, "word": "IFRS17", "beforeLength": 375, "after": "보험계약의 회계 처리 방법을 정한 새 국제회계기준으로, 우리나라는 2023년부터 시행했어요. 보험사가 앞으로 지급할 보험금 같은 부채를 계약 당시 금리가 아니라 매 결산 시점의 시장금리로 다시 평가해요. 수익도 보험료를 받을 때가 아니라 보장 기간에 나눠 잡아요."}, {"id": 698, "word": "IMF 스탠드바이협약", "beforeLength": 473, "after": "갑자기 외화가 부족해진 회원국에 국제통화기금이 신속하게 돈을 빌려주기로 맺는 협약이에요. 출자금의 일정 한도를 넘는 돈을 빌리려면 이 협약을 맺고 정해진 경제 개혁 조건을 지켜야 해요. 우리나라도 1997년 외환위기 때 이 방식으로 지원을 받았어요."}, {"id": 699, "word": "IMF 쿼타", "beforeLength": 684, "after": "회원국이 국제통화기금에 내는 출자금이에요. 경제 규모 등을 반영해 나라별 금액이 정해지고, 이에 따라 투표권과 빌릴 수 있는 돈의 한도, 특별인출권(SDR) 배분 규모가 달라져요. 그래서 출자 비중이 커지면 국제 금융 무대에서 그 나라의 발언권도 커져요."}, {"id": 700, "word": "J커브효과", "beforeLength": 406, "after": "환율이 올라도 경상수지가 처음엔 오히려 나빠졌다가 시간이 지나야 좋아지는 현상이에요. 수출품 가격은 바로 싸지지만 수출 물량이 늘기까지는 시간이 걸려 초기엔 수출 금액이 줄기 때문이에요. 경상수지 변화를 그래프로 그리면 알파벳 J 모양이 돼서 이런 이름이 붙었어요."}, {"id": 702, "word": "M&A", "beforeLength": 402, "after": "다른 회사를 사들이거나 둘 이상의 회사를 하나로 합쳐 경영권을 얻는 것을 말해요. 상대 회사 주식을 사서 지배권을 갖거나, 회사끼리 합병하거나, 특정 사업부만 넘겨받는 방식이 있어요. 새 회사를 처음부터 키우는 것보다 빠르게 시장과 기술을 얻을 수 있어 성장 전략으로 많이 써요."}, {"id": 703, "word": "MOVE", "beforeLength": 390, "after": "미국 국채 옵션 가격을 바탕으로 채권시장이 앞으로 얼마나 출렁일지에 대한 기대를 숫자로 나타낸 지수예요. 2년·5년·10년·30년 만기 국채의 1개월 옵션 변동성을 모아 계산해요. 값이 크게 오르면 금리 전망이 불확실하다는 신호라서 채권시장의 공포지수로 불리기도 해요."}, {"id": 704, "word": "MSCI 지수", "beforeLength": 445, "after": "미국의 모건스탠리캐피털인터내셔널이 작성해 발표하는 세계 주가지수예요. 전 세계에 투자하는 대형 펀드와 글로벌 자산운용사가 나라별 투자 비중을 정할 때 기준으로 삼아요. 그래서 어떤 나라가 선진국 지수에 들어가는지 여부가 외국인 자금 흐름에 큰 영향을 줘요."}, {"id": 705, "word": "N-B SRS", "beforeLength": 304, "after": "은행들이 서로 돈을 빌려주고 거래하며 얽힌 연결망을 통해 번지는 위험을 측정하는 지표예요. 각 은행의 부도 가능성과 은행끼리의 거래 규모를 함께 따져 위험 총량을 계산해요. 한 은행의 문제가 다른 은행으로 옮겨 붙어 금융 시스템 전체가 흔들릴 가능성을 점검할 때 써요."}, {"id": 706, "word": "NFC(Near Field Communication) 기술", "beforeLength": 462, "after": "보통 10cm 안의 아주 가까운 거리에서 기기끼리 데이터를 주고받는 무선통신 기술이에요. 블루투스처럼 따로 연결 설정을 하지 않아도 기기를 갖다 대기만 하면 바로 통신이 돼요. 거리가 짧아 보안에 유리해서 스마트폰 결제, 교통카드, 출입 인증 등에 널리 쓰여요."}, {"id": 707, "word": "Nowcasting", "beforeLength": 363, "after": "지금과 아주 가까운 미래의 경제 상황을 실시간에 가깝게 추정하는 기법이에요. 카드 결제액, 전기 사용량, 교통량처럼 바로 구할 수 있는 자료로 아직 발표되지 않은 GDP 같은 지표를 미리 가늠해요. 공식 통계는 한참 뒤에 나와서 정책 결정을 앞당기는 데 도움이 돼요."}, {"id": 708, "word": "OIS", "beforeLength": 249, "after": "하루짜리 초단기 금리와 고정금리를 일정 기간 서로 맞바꾸는 금리스왑 계약이에요. 원금은 주고받지 않고 기간 동안 쌓인 하루짜리 금리와 고정금리의 차이만 정산해요. 금융기관이 단기금리 변동 위험을 줄이는 데 쓰고, 그 금리는 시장이 예상하는 정책금리 흐름을 보여 줘요."}, {"id": 709, "word": "P2P대출", "beforeLength": 960, "after": "은행 같은 전통 금융회사 대신 온라인 플랫폼이 돈을 빌려줄 사람과 빌릴 사람을 연결해 주는 대출이에요. 여러 투자자의 돈을 모아 개인이나 기업에 빌려주고, 투자자는 대출 이자에서 수익을 얻어요. 은행보다 문턱이 낮을 수 있지만 돈을 떼일 위험은 투자자가 떠안아요."}, {"id": 710, "word": "PF-ABCP", "beforeLength": 330, "after": "부동산 개발사업 대출을 기초자산으로 삼아 특수목적회사가 발행하는 단기 기업어음이에요. 개발사업 쪽은 일반 투자자에게서 돈을 끌어올 수 있고, 투자자는 시공사 보증이나 증권사 매입약정 같은 안전장치를 믿고 투자해요. 만기가 짧아 부동산 경기가 나빠지면 자금줄이 막힐 위험이 있어요."}, {"id": 711, "word": "SOFR", "beforeLength": 390, "after": "미국 국채를 담보로 하루 동안 돈을 빌릴 때 실제로 거래된 금리를 바탕으로 한 기준금리예요. 뉴욕 연준이 매일 발표하며, 은행들의 호가가 아니라 실제 거래로 계산해 조작하기 어려워요. 조작 사건으로 신뢰를 잃은 리보 금리를 대신해 달러 대출과 파생상품의 기준이 됐어요."}, {"id": 712, "word": "SWIFT", "beforeLength": 367, "after": "전 세계 은행들이 송금·결제 관련 메시지를 안전하게 주고받는 국제금융통신망이에요. 해외 송금을 하면 돈 자체가 아니라 누구에게 얼마를 보내라는 지시가 이 망을 통해 은행 사이에 전달돼요. 1973년 브뤼셀에서 설립됐고, 이 망에서 빠지면 국제 거래가 막혀 제재 수단으로도 쓰여요."}, {"id": 713, "word": "Treasury Bill(T/B)", "beforeLength": 567, "after": "미국 재무부가 발행하는 만기 1년 이하의 단기 국채예요. 이자를 따로 주지 않고 액면가보다 싸게 팔았다가 만기에 액면가를 돌려주는 할인 방식으로 수익을 줘요. 사실상 떼일 위험이 없고 거래도 활발해 단기금융시장에서 가장 안전한 투자처 중 하나로 꼽혀요."}, {"id": 714, "word": "V-KOSPI", "beforeLength": 422, "after": "코스피200 옵션 가격으로 계산한, 투자자들이 예상하는 한국 증시의 앞으로의 변동성 지수예요. 주가가 급락할 때 크게 오르는 경향이 있어 흔히 공포지수라고 불러요. 미국 증시의 VIX와 비슷한 개념으로, 시장 불안이 얼마나 큰지 가늠하는 데 쓰여요."}, {"id": 715, "word": "VAN사업자", "beforeLength": 616, "after": "카드로 결제할 때 가맹점과 카드사 사이에서 결제 정보를 전달해 주는 부가가치통신망 사업자예요. 가게 단말기에서 카드를 긁으면 이 업체의 망을 거쳐 카드사로 승인 요청이 가고 결과가 되돌아와요. 단말기 설치·관리와 매출 전표 처리도 맡아 카드 결제가 돌아가게 하는 숨은 연결고리예요."}, {"id": 716, "word": "VaR(Value at Risk)", "beforeLength": 202, "after": "정해진 기간과 확률 수준에서 시장 가격이 불리하게 움직일 때 생길 수 있는 최대 손실 예상액이에요. 하루 동안 99% 신뢰수준의 값이 5억 원이라면, 하루 손실이 5억 원을 넘지 않을 확률이 99%라는 뜻이에요. 금융기관이 보유 자산의 위험을 하나의 금액으로 파악하고 관리하는 데 써요."}, {"id": 717, "word": "직접금융", "beforeLength": 672, "after": "기업 같은 자금 수요자가 주식이나 채권을 발행해 투자자에게서 직접 돈을 조달하는 방식이에요. 증권회사가 발행과 판매를 도와도, 돈을 대는 사람이 곧 기업의 주주나 채권자가 된다는 점이 핵심이에요. 은행이 예금을 모아 대신 빌려주는 간접금융과 달리 투자 위험을 투자자가 직접 져요."}, {"id": 718, "word": "직접세", "beforeLength": 577, "after": "세금을 내야 하는 사람과 실제로 부담하는 사람이 같은 세금이에요. 소득세·법인세·상속세처럼 내 소득이나 재산에 매겨져 다른 사람에게 부담을 넘길 수 없어요. 물건값에 포함돼 소비자가 대신 부담하는 부가가치세 같은 간접세와 대비돼요."}, {"id": 719, "word": "전업주의", "beforeLength": 824, "after": "은행은 은행 업무만, 증권사는 증권 업무만, 보험사는 보험 업무만 하도록 금융 업무를 나누는 방식이에요. 한 회사의 손실이나 이해 충돌이 다른 업무로 번지는 것을 막으려는 취지예요. 한 회사가 여러 업무를 함께 하는 겸업주의와 대비되며, 세계적으로는 겸업 쪽이 대세예요."}, {"id": 720, "word": "비경제활동인구", "beforeLength": 591, "after": "만 15세 이상 인구 가운데 일하고 있지도 않고 일자리를 찾고 있지도 않은 사람이에요. 학업에 전념하는 학생, 집안일을 하는 사람, 은퇴한 노인, 취업을 아예 포기한 사람 등이 여기에 들어가요. 실업자로 세지 않기 때문에 이들이 늘면 실업률이 낮아져 보일 수 있어요."}, {"id": 721, "word": "경제활동참가율", "beforeLength": 591, "after": "만 15세 이상 인구 중 일을 하고 있거나 적극적으로 일자리를 찾고 있는 사람의 비율이에요. 취업자와 실업자를 합친 경제활동인구를 15세 이상 인구로 나눠 구해요. 이 비율이 낮으면 일할 의사가 없는 사람이 많다는 뜻이라 실업률과 함께 고용 상황을 보는 데 써요."}, {"id": 722, "word": "자유변동환율제도", "beforeLength": 711, "after": "외환의 수요와 공급에 따라 시장에서 환율이 자유롭게 정해지는 제도예요. 달러를 사려는 사람이 많으면 원·달러 환율이 오르고, 팔려는 사람이 많으면 내려가요. 정부가 환율을 일정하게 묶는 고정환율제와 달리 대외 충격을 환율이 흡수해 주지만 변동이 커질 수 있어요."}, {"id": 723, "word": "국민총처분가능소득(GNDI)", "beforeLength": 644, "after": "나라 전체가 소비나 저축에 자유롭게 쓸 수 있는 소득을 감가상각을 빼기 전 기준으로 합친 금액이에요. 국민이 번 소득에 해외 교포 송금처럼 대가 없이 들어온 돈을 더하고, 해외에 무상으로 보낸 돈을 빼서 구해요. 여기서 소비를 빼면 총저축이 되므로 저축률 계산의 바탕이 돼요."}, {"id": 724, "word": "복리", "beforeLength": 905, "after": "이자를 원금에 더한 뒤, 그 합계에 다시 이자를 붙여 계산하는 방식이에요. 100만 원을 연 10% 조건으로 맡기면 1년 뒤 110만 원, 2년 뒤에는 110만 원의 10%가 붙어 121만 원이 돼요. 원금에만 이자를 주는 단리보다 기간이 길수록 차이가 눈덩이처럼 커져요."}, {"id": 725, "word": "복수금리방식", "beforeLength": 490, "after": "경쟁입찰에서 낙찰된 사람마다 자기가 써낸 금리를 그대로 적용받는 방식이에요. 같은 입찰이라도 낮은 금리를 쓴 사람과 높은 금리를 쓴 사람이 서로 다른 금리를 받게 돼요. 낙찰자 모두에게 하나의 금리를 똑같이 적용하는 단일금리방식과 대비돼요."}, {"id": 727, "word": "익익일결제", "beforeLength": 451, "after": "외환을 거래하기로 계약한 날로부터 이틀째 되는 영업일에 대금을 주고받는 결제 방식이에요. 나라마다 영업일과 시간대가 달라 확인과 송금에 시간이 필요하기 때문에 생긴 관행이에요. 현물환 거래의 표준 결제일로, 당일결제나 다음 날 결제보다 훨씬 흔하게 쓰여요."}, {"id": 728, "word": "커플링", "beforeLength": 429, "after": "한 나라의 경제나 주가·금리 같은 지표가 다른 나라나 세계 경제와 같은 방향으로 움직이는 현상이에요. 예를 들어 미국 증시가 오를 때 한국 증시도 함께 오르는 모습이 여기에 해당해요. 반대로 따로 움직이는 것은 디커플링이라고 하며, 세계 경제가 서로 얽힐수록 동조화가 강해져요."}, {"id": 729, "word": "리스크 오프(Risk Off)", "beforeLength": 429, "after": "경기나 시장이 불안할 때 투자자들이 위험한 자산을 팔고 안전한 자산으로 돈을 옮기는 분위기예요. 주식이나 암호화폐에서 빠져나온 돈이 채권·금·달러 같은 곳으로 몰려요. 투자자들이 낙관적이어서 위험 자산에 적극 투자하는 리스크 온과 반대되는 상황이에요."}, {"id": 730, "word": "환가료", "beforeLength": 500, "after": "은행이 수출 대금 같은 외화를 실제로 받기 전에 고객에게 원화를 먼저 내줄 때 받는 이자 성격의 수수료예요. 수출환어음을 사들인 은행은 원화를 바로 지급하지만 외화는 며칠 뒤에야 들어와 그동안 돈을 빌려준 셈이 돼요. 그 기간의 자금 부담을 보상받는 것이라 기간이 길수록 금액이 커져요."}, {"id": 731, "word": "실질국내총생산", "beforeLength": 492, "after": "한 나라에서 생산된 최종 생산물의 가치를 기준연도 가격으로 계산한 국내총생산이에요. 가격이 올라서 생긴 증가분을 빼고 실제 생산량이 얼마나 늘었는지만 보여 줘요. 그래서 경제성장률을 계산할 때 쓰이고, 그해 가격으로 계산하는 명목 국내총생산과 구별돼요."}, {"id": 732, "word": "실질금리", "beforeLength": 524, "after": "겉으로 보이는 명목금리에서 물가상승률을 빼서, 돈의 실제 가치 기준으로 본 금리예요. 예금금리가 연 4%여도 물가가 3% 오르면 실제로 늘어난 구매력은 1% 정도뿐이에요. 물가가 금리보다 더 오르면 마이너스가 되어 예금을 해도 실제로는 손해를 볼 수 있어요."}, {"id": 733, "word": "실질소득", "beforeLength": 735, "after": "물가 변동을 반영해 그 돈으로 실제 얼마나 살 수 있는지를 기준으로 본 소득이에요. 월급이 5% 올라도 물가가 5% 올랐다면 살 수 있는 물건의 양은 그대로라 형편이 나아진 게 아니에요. 그래서 생활 수준이 정말 좋아졌는지 판단할 때는 명목소득보다 이것을 봐야 해요."}, {"id": 734, "word": "유통정지화폐", "beforeLength": 457, "after": "법적으로 돈으로서 쓸 수 있는 효력을 잃어 더는 지급에 사용할 수 없는 옛 화폐예요. 우리나라에서는 1962년 제2차 통화조치 이전에 발행된 화폐가 여기에 해당해요. 새로 찍지만 않을 뿐 여전히 쓸 수 있는 발행중지화폐와 달리 물건값으로 낼 수 없어요."}, {"id": 735, "word": "무권화", "beforeLength": 378, "after": "종이 증권을 아예 발행하지 않고 전자 장부에 등록하는 것만으로 권리를 관리하는 방식이에요. 주식이나 채권을 사고팔면 실물이 오가지 않고 전자 등록 기록만 바뀌어요. 분실·도난이나 위조 위험이 사라지고 처리 비용도 줄어 우리나라도 전자증권제도로 이를 시행하고 있어요."}, {"id": 736, "word": "하드랜딩", "beforeLength": 561, "after": "빠르게 성장하던 경제가 갑자기 급격한 침체에 빠지는 것을 말해요. 정책을 급하게 바꾸거나 큰 외부 충격이 오면 성장률이 뚝 떨어지고 실업이 크게 늘어요. 비행기가 충격 없이 내려앉듯 서서히 식는 소프트랜딩과 반대되는 말로, 경착륙이라고도 해요."}, {"id": 737, "word": "명목화폐", "beforeLength": 433, "after": "종이나 금속 자체의 가치는 거의 없지만 국가가 정한 액면가대로 돈으로 쓰이는 화폐예요. 만원권을 만드는 비용은 만 원보다 훨씬 적지만, 법과 사람들의 신뢰 덕분에 만 원의 가치를 가져요. 금화처럼 재료 자체가 값어치를 지니는 실물화폐와 대비되는 개념이에요."}, {"id": 738, "word": "연방준비은행(FRB)", "beforeLength": 552, "after": "미국 중앙은행 제도인 연방준비제도 아래 12개 지역에 하나씩 있는 지역 준비은행이에요. 각 지역의 은행을 감독하고 화폐를 공급하며, 지역 경제 상황을 조사해 정책 결정에 반영해요. 뉴욕에 있는 은행은 공개시장운영을 실제로 수행해 특히 중요한 역할을 맡아요."}, {"id": 739, "word": "위험가중치", "beforeLength": 406, "after": "은행 자산의 위험 정도에 따라 매기는 비율로, 위험가중자산을 계산할 때 곱하는 값이에요. 예를 들어 국채처럼 안전한 자산은 낮은 비율을, 신용이 낮은 기업 대출은 높은 비율을 적용해요. 같은 금액이라도 위험한 자산을 많이 가질수록 자기자본을 더 쌓아야 하게 만드는 장치예요."}, {"id": 740, "word": "비정규직", "beforeLength": 595, "after": "계약직·일용직·시간제·파견직처럼 근로 기간이 정해져 있거나 고용 형태가 일반적이지 않은 일자리예요. 기간 정함 없이 직접 고용돼 전일제로 일하는 정규직과 달리 계약이 끝나는 시점이 정해진 경우가 많아요. 고용이 불안하고 임금·복지 차이가 커서 노동시장의 주요 과제로 꼽혀요."}, {"id": 741, "word": "제조업가동률지수", "beforeLength": 434, "after": "제조업체의 생산능력 대비 실제 생산 비율인 가동률을 기준연도 100과 비교해 나타낸 지수예요. 공장 설비를 얼마나 쉬지 않고 돌리는지 보여 줘서 지수가 오르면 생산이 활발하다는 뜻이에요. 경기가 좋아지면 오르고 나빠지면 내려가서 경기 흐름을 판단하는 기초 자료로 써요."}, {"id": 742, "word": "융통어음", "beforeLength": 499, "after": "실제 물건 거래 없이 순전히 돈을 마련할 목적으로 발행하는 어음이에요. 물품 대금을 치르기 위해 발행하는 진성어음과 겉모양은 같지만, 뒤에 실제 거래가 없다는 점이 달라요. 갚을 재원이 거래에서 나오지 않아 부도 위험이 상대적으로 크다고 봐요."}, {"id": 743, "word": "평균소비성향", "beforeLength": 425, "after": "처분가능소득 가운데 소비로 쓴 돈이 차지하는 비율이에요. 처분가능소득이 300만 원인 가구가 210만 원을 쓰면 이 값은 0.7이에요. 1에서 이 값을 빼면 평균저축성향이 되고, 새로 늘어난 소득만 따지는 한계소비성향과는 구별돼요."}, {"id": 744, "word": "평균저축성향", "beforeLength": 425, "after": "처분가능소득 가운데 쓰지 않고 남긴 돈, 즉 저축이 차지하는 비율이에요. 1에서 소득 중 소비로 쓴 비율인 평균소비성향을 빼서 구해요. 처분가능소득 300만 원 중 90만 원을 남겼다면 0.3으로, 높을수록 미래를 위해 더 많이 모아 둔다는 뜻이에요."}, {"id": 745, "word": "중간수요", "beforeLength": 260, "after": "다른 물건을 만드는 과정에 원재료로 들어가는 재화와 서비스에 대한 수요예요. 같은 우유라도 가정에서 마시려고 사면 최종수요지만, 아이스크림 공장이 재료로 사면 여기에 해당해요. 산업 간 거래 흐름을 분석할 때 소비·투자 같은 최종수요와 나눠서 봐요."}, {"id": 746, "word": "말잔", "beforeLength": 550, "after": "월말이나 분기말처럼 정해진 기간의 마지막 날 시점에 남아 있는 잔액이에요. 예를 들어 6월 말 잔액은 6월 30일 하루의 잔액만 보고, 그 전 날짜들의 움직임은 반영하지 않아요. 계산이 간단해 결산에 많이 쓰지만, 기간 끝에 잠깐 늘거나 줄면 실제 흐름과 달라 평잔과 함께 봐요."}, {"id": 747, "word": "환차익", "beforeLength": 629, "after": "환율이 바뀌면서 외화 자산이나 부채를 원화로 다시 따졌을 때 생기는 이익이에요. 달러 예금을 가진 상태에서 원·달러 환율이 오르면 원화로 바꾼 가치가 커져 이익이 나요. 반대로 달러 빚이 있을 때는 환율이 내리면 갚을 원화가 줄어 이익이 생겨요."}]$payload$::jsonb;
  v_bad text;
BEGIN
  PERFORM set_config('lock_timeout', '10s', true);
  IF (SELECT count(*) FROM public.words_detailed_meaning_backup_v1 WHERE id IN (627,628,629,630,631,632,633,634,635,636,637,638,639,640,641,642,643,644,645,646,647,648,649,650,652,653,654,655,656,657,658,659,660,661,662,663,664,665,666,667,668,669,670,671,672,673,674,675,677,678,679,680,681,682,683,684,685,686,687,688,689,690,691,692,693,694,695,696,697,698,699,700,702,703,704,705,706,707,708,709,710,711,712,713,714,715,716,717,718,719,720,721,722,723,724,725,727,728,729,730,731,732,733,734,735,736,737,738,739,740,741,742,743,744,745,746,747)) <> 117 THEN RAISE EXCEPTION 'backup rows missing; cannot restore'; END IF;
  SELECT string_agg(r.id::text, ',') INTO v_bad
  FROM jsonb_to_recordset(v_payload) AS r(id integer, word text, "beforeLength" integer, after text) JOIN public.words w ON w.id = r.id
  WHERE w.detailed_meaning IS DISTINCT FROM r.after;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'rows changed after revision: %', v_bad; END IF;
  UPDATE public.words w SET detailed_meaning = b.detailed_meaning
  FROM public.words_detailed_meaning_backup_v1 b WHERE w.id = b.id AND w.word = b.word AND b.id IN (627,628,629,630,631,632,633,634,635,636,637,638,639,640,641,642,643,644,645,646,647,648,649,650,652,653,654,655,656,657,658,659,660,661,662,663,664,665,666,667,668,669,670,671,672,673,674,675,677,678,679,680,681,682,683,684,685,686,687,688,689,690,691,692,693,694,695,696,697,698,699,700,702,703,704,705,706,707,708,709,710,711,712,713,714,715,716,717,718,719,720,721,722,723,724,725,727,728,729,730,731,732,733,734,735,736,737,738,739,740,741,742,743,744,745,746,747);
  IF (SELECT count(*) FROM public.words w JOIN public.words_detailed_meaning_backup_v1 b USING (id) WHERE b.id IN (627,628,629,630,631,632,633,634,635,636,637,638,639,640,641,642,643,644,645,646,647,648,649,650,652,653,654,655,656,657,658,659,660,661,662,663,664,665,666,667,668,669,670,671,672,673,674,675,677,678,679,680,681,682,683,684,685,686,687,688,689,690,691,692,693,694,695,696,697,698,699,700,702,703,704,705,706,707,708,709,710,711,712,713,714,715,716,717,718,719,720,721,722,723,724,725,727,728,729,730,731,732,733,734,735,736,737,738,739,740,741,742,743,744,745,746,747) AND w.detailed_meaning = b.detailed_meaning) <> 117 THEN
    RAISE EXCEPTION 'restored row count mismatch';
  END IF;
  DELETE FROM public.words_detailed_meaning_backup_v1 WHERE id IN (627,628,629,630,631,632,633,634,635,636,637,638,639,640,641,642,643,644,645,646,647,648,649,650,652,653,654,655,656,657,658,659,660,661,662,663,664,665,666,667,668,669,670,671,672,673,674,675,677,678,679,680,681,682,683,684,685,686,687,688,689,690,691,692,693,694,695,696,697,698,699,700,702,703,704,705,706,707,708,709,710,711,712,713,714,715,716,717,718,719,720,721,722,723,724,725,727,728,729,730,731,732,733,734,735,736,737,738,739,740,741,742,743,744,745,746,747);
END
